<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import InputError from '@/Components/InputError.vue'; import ValidationSummary from '@/Components/ValidationSummary.vue'; import {Head,useForm,router} from '@inertiajs/vue3'; import {reactive} from 'vue'; const props=defineProps<{users:any[];customers:any[];filters:any}>(); const filters=reactive({...props.filters}); const apply=()=>router.get(route('admin.users.index'),filters,{preserveState:true,replace:true}); const reset=()=>{filters.search='';apply()}; const form=useForm({customer_id:'',name:'',email:'',password:''});</script>
<template><Head title="Customer users"/><AuthenticatedLayout><template #header><h2 class="text-xl font-semibold">Customer users</h2></template><div class="mx-auto max-w-5xl space-y-5 p-6"><form @submit.prevent="form.post(route('admin.users.store'))" class="grid gap-2 bg-white p-4 shadow sm:grid-cols-5"><div><select v-model="form.customer_id" required class="w-full rounded border-gray-300"><option value="">Customer</option><option v-for="c in customers" :value="c.id">{{c.name}}</option></select><InputError :message="form.errors.customer_id" class="mt-1"/></div><div><input v-model="form.name" placeholder="Name" required class="w-full rounded border-gray-300"><InputError :message="form.errors.name" class="mt-1"/></div><div><input v-model="form.email" placeholder="Email" required class="w-full rounded border-gray-300"><InputError :message="form.errors.email" class="mt-1"/></div><div><input v-model="form.password" type="password" placeholder="Temporary password" required class="w-full rounded border-gray-300"><InputError :message="form.errors.password" class="mt-1"/></div><button class="rounded bg-indigo-600 text-white">Create</button><div class="sm:col-span-5"><ValidationSummary :errors="form.errors"/></div></form><form @submit.prevent="apply" class="flex gap-2"><input v-model="filters.search" placeholder="Search name, email, customer" class="rounded border-gray-300"><button class="rounded bg-gray-800 px-3 text-white">Search</button><button type="button" @click="reset" class="text-gray-600">Reset</button></form><div class="bg-white shadow"><div v-for="user in users" :key="user.id" class="border-b p-4"><b>{{user.name}}</b> — {{user.email}} <span class="text-sm text-gray-500">{{user.customer?.name}}</span></div><p v-if="!users.length" class="p-4 text-gray-600">No customer users match your search.</p></div></div></AuthenticatedLayout></template>
